import{_ as a,a as o,c as t,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第二册：实践与进步 · 全册易错点 · 第74–96课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第二册：实践与进步 · 全册易错点 · 第74–96课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-2/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 全册易错点 · 第50–73课","link":"/life/english/new-concept/book-2/mistakes-part-03"},"next":{"text":"第二册：实践与进步 · 综合复习与自测","link":"/life/english/new-concept/book-2/review"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 全册易错点 · 第50–73课","link":"/life/english/new-concept/book-2/mistakes-part-03"},"next":{"text":"第二册：实践与进步 · 综合复习与自测","link":"/life/english/new-concept/book-2/review"}},"headers":[],"relativePath":"life/english/new-concept/book-2/mistakes-part-04.md","filePath":"life/english/new-concept/book-2/mistakes-part-04.md"}'),i={name:"life/english/new-concept/book-2/mistakes-part-04.md"};function l(r,e,s,h,p,d){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-全册易错点-·-第74–96课" tabindex="-1">第二册：实践与进步 · 全册易错点 · 第74–96课 <a class="header-anchor" href="#第二册-实践与进步-·-全册易错点-·-第74–96课" aria-label="Permalink to &quot;第二册：实践与进步 · 全册易错点 · 第74–96课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><h2 id="l74-·-定语从句与指代" tabindex="-1">L74 · 定语从句与指代 <a class="header-anchor" href="#l74-·-定语从句与指代" aria-label="Permalink to &quot;L74 · 定语从句与指代 {#l74-·-定语从句与指代}&quot;">​</a></h2><p>The visitor who recognised the actor smiled. 中 who 作 recognised 的主语，意思是“认出演员的那位游客笑了”。The visitor who he recognised smiled. 也合法：he 作从句主语，who 作宾语，意思是“他认出的那位游客笑了”。若要表达前一种意思，不能写 The visitor who he recognised the actor smiled.；从句已有主语 he 和宾语 the actor，再加 who 会造成成分重复。</p><p><strong>对照例句：</strong> The visitor who recognised the actor kept her secret.</p><p>who 指 the visitor 并作 recognised 的主语；kept 是主句谓语，her 指前文 actor。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-074">回看讲解和练习</a></p><h2 id="l75-·-不定式与目的" tabindex="-1">L75 · 不定式与目的 <a class="header-anchor" href="#l75-·-不定式与目的" aria-label="Permalink to &quot;L75 · 不定式与目的 {#l75-·-不定式与目的}&quot;">​</a></h2><p>lie 表躺下，过去式 lay；lay 表放置，过去式 laid，本例需要有宾语的 laid。</p><p><strong>对照例句：</strong> The hikers laid bright jackets on the rocks to attract attention.</p><p>laid 为 lay 的过去式，bright jackets 是宾语，to attract 为目的状语，执行者与 hikers 一致。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-075">回看讲解和练习</a></p><h2 id="l76-·-间接引语与视角转换" tabindex="-1">L76 · 间接引语与视角转换 <a class="header-anchor" href="#l76-·-间接引语与视角转换" aria-label="Permalink to &quot;L76 · 间接引语与视角转换 {#l76-·-间接引语与视角转换}&quot;">​</a></h2><p>believe a person 表相信其所说，believe in a person 更偏信任其能力或品格。</p><p><strong>对照例句：</strong> The programme claimed that the trees could grow blue apples.</p><p>claimed 为报告动词，that 从句是被声称的内容；could 是从过去视角表达能力，句子不证明该能力真实。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-076">回看讲解和练习</a></p><h2 id="l77-·-现在完成时与过去时间" tabindex="-1">L77 · 现在完成时与过去时间 <a class="header-anchor" href="#l77-·-现在完成时与过去时间" aria-label="Permalink to &quot;L77 · 现在完成时与过去时间 {#l77-·-现在完成时与过去时间}&quot;">​</a></h2><p>enough healthy 的次序不对；形容词后放 enough，如 healthy enough。</p><p><strong>对照例句：</strong> The injured bird has recovered enough to stand on both feet.</p><p>has recovered 为完成时，enough to stand 表达到某种程度，on both feet 说明动作状态。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-077">回看讲解和练习</a></p><h2 id="l78-·-动名词与动词搭配" tabindex="-1">L78 · 动名词与动词搭配 <a class="header-anchor" href="#l78-·-动名词与动词搭配" aria-label="Permalink to &quot;L78 · 动名词与动词搭配 {#l78-·-动名词与动词搭配}&quot;">​</a></h2><p>He stopped to buy cigarettes 表示停下来买烟，意思与停止买烟相反。</p><p><strong>对照例句：</strong> Jon stopped buying cigarettes on his way to work.</p><p>stopped 为谓语，buying 作动名词宾语，on his way to work 是购买发生的情境。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-078">回看讲解和练习</a></p><h2 id="l79-·-时间、原因与让步从句" tabindex="-1">L79 · 时间、原因与让步从句 <a class="header-anchor" href="#l79-·-时间、原因与让步从句" aria-label="Permalink to &quot;L79 · 时间、原因与让步从句 {#l79-·-时间、原因与让步从句}&quot;">​</a></h2><p>despite it was late 结构不对；可用 despite the delay 或 although it was late。</p><p><strong>对照例句：</strong> Despite the delay, we enjoyed the view from the plane.</p><p>Despite the delay 是介词短语，主句 enjoyed 为过去式，from the plane 给出观察位置。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-079">回看讲解和练习</a></p><h2 id="l80-·-被动语态与信息重点" tabindex="-1">L80 · 被动语态与信息重点 <a class="header-anchor" href="#l80-·-被动语态与信息重点" aria-label="Permalink to &quot;L80 · 被动语态与信息重点 {#l80-·-被动语态与信息重点}&quot;">​</a></h2><p>was build 错误，build 的过去分词是 built。</p><p><strong>对照例句：</strong> The exhibition hall was built from glass and steel.</p><p>was built 为一般过去被动，from glass and steel 说明建材；主语是展厅而非建造者。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-080">回看讲解和练习</a></p><h2 id="l81-·-分词修饰与逻辑主语" tabindex="-1">L81 · 分词修饰与逻辑主语 <a class="header-anchor" href="#l81-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;L81 · 分词修饰与逻辑主语 {#l81-·-分词修饰与逻辑主语}&quot;">​</a></h2><p>Dressed as a cleaner, the gate opened 会使分词逻辑主语变成门，形成悬垂结构。</p><p><strong>对照例句：</strong> Dressed as a cleaner, the prisoner walked towards the side gate.</p><p>Dressed 为过去分词状语，逻辑主语是 prisoner；walked 为主句谓语，towards 表方向。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-081">回看讲解和练习</a></p><h2 id="l82-·-情态动词的意义与形式" tabindex="-1">L82 · 情态动词的意义与形式 <a class="header-anchor" href="#l82-·-情态动词的意义与形式" aria-label="Permalink to &quot;L82 · 情态动词的意义与形式 {#l82-·-情态动词的意义与形式}&quot;">​</a></h2><p>might was 不合结构；过去推测用 might have been。</p><p><strong>对照例句：</strong> The shape in the photograph might have been a large fish.</p><p>might have been 为对过去身份的推测，a large fish 为表语；might 表不确定，不是过去能力。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-082">回看讲解和练习</a></p><h2 id="l83-·-将来表达与安排" tabindex="-1">L83 · 将来表达与安排 <a class="header-anchor" href="#l83-·-将来表达与安排" aria-label="Permalink to &quot;L83 · 将来表达与安排 {#l83-·-将来表达与安排}&quot;">​</a></h2><p>by June 与 in June 不同：前者指最迟到该时间，后者指在该月内。</p><p><strong>对照例句：</strong> The candidate promised that the council would publish a plan by June.</p><p>promised 明确信息来源，would publish 是过去视角的将来，by June 表截止时间。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-083">回看讲解和练习</a></p><h2 id="l84-·-将来进行时与过程" tabindex="-1">L84 · 将来进行时与过程 <a class="header-anchor" href="#l84-·-将来进行时与过程" aria-label="Permalink to &quot;L84 · 将来进行时与过程 {#l84-·-将来进行时与过程}&quot;">​</a></h2><p>discuss about the offer 多余 about；discuss 直接接宾语。</p><p><strong>对照例句：</strong> At ten tomorrow, the two sides will be discussing the revised offer.</p><p>will be discussing 为将来进行时，the two sides 是复数主语，revised 为过去分词定语。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-084">回看讲解和练习</a></p><h2 id="l85-·-不定式与目的" tabindex="-1">L85 · 不定式与目的 <a class="header-anchor" href="#l85-·-不定式与目的" aria-label="Permalink to &quot;L85 · 不定式与目的 {#l85-·-不定式与目的}&quot;">​</a></h2><p>enough confident 语序错误，应为 confident enough；too old 与 very old 意义不同。</p><p><strong>对照例句：</strong> Ruth was nervous, but she was not too old to learn coding.</p><p>not too old to learn 否定年龄成为绝对障碍；to learn 为结果相关不定式，coding 是 learn 的宾语内容。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-085">回看讲解和练习</a></p><h2 id="l86-·-分词修饰与逻辑主语" tabindex="-1">L86 · 分词修饰与逻辑主语 <a class="header-anchor" href="#l86-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;L86 · 分词修饰与逻辑主语 {#l86-·-分词修饰与逻辑主语}&quot;">​</a></h2><p>Hearing a sound, the wheel broke 让 wheel 成听声者，不符合意思。</p><p><strong>对照例句：</strong> Hearing a strange sound, the driver slowed down immediately.</p><p>Hearing 的执行者是 driver；slowed down 为主句谓语，immediately 是时间方式相关副词。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-086">回看讲解和练习</a></p><h2 id="l87-·-间接引语与视角转换" tabindex="-1">L87 · 间接引语与视角转换 <a class="header-anchor" href="#l87-·-间接引语与视角转换" aria-label="Permalink to &quot;L87 · 间接引语与视角转换 {#l87-·-间接引语与视角转换}&quot;">​</a></h2><p>He said ... 不等于 It was proved ...；陈述和证据必须分别标识。</p><p><strong>对照例句：</strong> The officer asked where Daniel had been before eight.</p><p>asked 引出间接特殊疑问，where 从句按主语 Daniel 加 had been 排列；before eight 是核对时段。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-087">回看讲解和练习</a></p><h2 id="l88-·-被动语态与信息重点" tabindex="-1">L88 · 被动语态与信息重点 <a class="header-anchor" href="#l88-·-被动语态与信息重点" aria-label="Permalink to &quot;L88 · 被动语态与信息重点 {#l88-·-被动语态与信息重点}&quot;">​</a></h2><p>through a pipe 指穿过管道内部；across a pipe 则是横跨，不适合输送通道。</p><p><strong>对照例句：</strong> Fresh air will be supplied through a narrow pipe.</p><p>will be supplied 是将来被动，through 引出通道，Fresh air 不可数。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-088">回看讲解和练习</a></p><h2 id="l89-·-动词、宾语与补足语" tabindex="-1">L89 · 动词、宾语与补足语 <a class="header-anchor" href="#l89-·-动词、宾语与补足语" aria-label="Permalink to &quot;L89 · 动词、宾语与补足语 {#l89-·-动词、宾语与补足语}&quot;">​</a></h2><p>Thursday 与 Tuesday 不是同一天；不能只因都以 T 开头而在时间安排中混用。</p><p><strong>对照例句：</strong> I meant to say Thursday, but I accidentally said Tuesday.</p><p>meant to say 表意图，said 是实际行为，but 标出意图与结果的不一致。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-089">回看讲解和练习</a></p><h2 id="l90-·-分词修饰与逻辑主语" tabindex="-1">L90 · 分词修饰与逻辑主语 <a class="header-anchor" href="#l90-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;L90 · 分词修饰与逻辑主语 {#l90-·-分词修饰与逻辑主语}&quot;">​</a></h2><p>We ran out potatoes 缺 of；Potatoes ran out 是另一种主语安排。</p><p><strong>对照例句：</strong> The potatoes fried this morning were used for supper.</p><p>fried this morning 是过去分词后置定语，were used 才是主句谓语，主语 potatoes 为复数。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-090">回看讲解和练习</a></p><h2 id="l91-·-过去进行时与叙事背景" tabindex="-1">L91 · 过去进行时与叙事背景 <a class="header-anchor" href="#l91-·-过去进行时与叙事背景" aria-label="Permalink to &quot;L91 · 过去进行时与叙事背景 {#l91-·-过去进行时与叙事背景}&quot;">​</a></h2><p>over the fields 是在田野上方；through the fields 通常表示从田地内部穿行。</p><p><strong>对照例句：</strong> We were drifting over the fields when the pilot noticed a clear landing area.</p><p>were drifting 为背景，when 引出 noticed；a clear landing area 首次引入新地点。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-091">回看讲解和练习</a></p><h2 id="l92-·-间接引语与视角转换" tabindex="-1">L92 · 间接引语与视角转换 <a class="header-anchor" href="#l92-·-间接引语与视角转换" aria-label="Permalink to &quot;L92 · 间接引语与视角转换 {#l92-·-间接引语与视角转换}&quot;">​</a></h2><p>rude 是形容词，rudely 是副词；meant to be 后用 rude，不是 rudely。</p><p><strong>对照例句：</strong> I do not think the receptionist meant to be rude.</p><p>do not think 否定判断，meant to be 表意图；说话者评价的是意图，而不是否认语气可能让人不舒服。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-092">回看讲解和练习</a></p><h2 id="l93-·-定语从句与指代" tabindex="-1">L93 · 定语从句与指代 <a class="header-anchor" href="#l93-·-定语从句与指代" aria-label="Permalink to &quot;L93 · 定语从句与指代 {#l93-·-定语从句与指代}&quot;">​</a></h2><p>非限制性从句通常不能用 that 替代 which，也不能省略关系代词。</p><p><strong>对照例句：</strong> The statue, which was donated by local artists, stands beside the library.</p><p>The statue 为主语，stands 为主句谓语；逗号内 which was donated 是非限制性定语从句，which 指 statue。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-093">回看讲解和练习</a></p><h2 id="l94-·-一般现在时与习惯" tabindex="-1">L94 · 一般现在时与习惯 <a class="header-anchor" href="#l94-·-一般现在时与习惯" aria-label="Permalink to &quot;L94 · 一般现在时与习惯 {#l94-·-一般现在时与习惯}&quot;">​</a></h2><p>practise to float 应改为 practise floating；learn floating 并非此处常用搭配。</p><p><strong>对照例句：</strong> The children practise floating before they learn to swim across the pool.</p><p>practise 后接动名词 floating，learn 后接 to swim；before 引出学习顺序，children 为复数。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-094">回看讲解和练习</a></p><h2 id="l95-·-非真实条件句" tabindex="-1">L95 · 非真实条件句 <a class="header-anchor" href="#l95-·-非真实条件句" aria-label="Permalink to &quot;L95 · 非真实条件句 {#l95-·-非真实条件句}&quot;">​</a></h2><p>would can store 错误；能力假设直接用 could，结果可用 would be able to。</p><p><strong>对照例句：</strong> If people could store sunlight in a pocket, winter evenings would look different.</p><p>could store 表非真实能力假设，would look 表设想结果；sunlight 不可数，in a pocket 为幻想中的容器。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-095">回看讲解和练习</a></p><h2 id="l96-·-被动语态与信息重点" tabindex="-1">L96 · 被动语态与信息重点 <a class="header-anchor" href="#l96-·-被动语态与信息重点" aria-label="Permalink to &quot;L96 · 被动语态与信息重点 {#l96-·-被动语态与信息重点}&quot;">​</a></h2><p>by 不总是被动执行者：by the river 表在河边，不是河流摆放灯笼。</p><p><strong>对照例句：</strong> The lanterns are placed by the river to honour family ancestors.</p><p>are placed 是一般现在时被动，概括仪式做法；by the river 是地点而非执行者，to honour 表目的。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-096">回看讲解和练习</a></p>',118)])])}const u=a(i,[["render",l]]);export{g as __pageData,u as default};
